using System;
using System.Text;

namespace MobileOneMedia.DevDeckStudio
{
    public static class StudioAsset
    {
        public const string STUDIO_HTML_B64 = "";
        public const string FAVICON_PNG_B64 = "";

        public static byte[] GetStudioHtmlBytes()
        {
            return Convert.FromBase64String(STUDIO_HTML_B64);
        }

        public static byte[] GetFaviconBytes()
        {
            return Convert.FromBase64String(FAVICON_PNG_B64);
        }
    }
}